    code: "class Repo:\n    def __init__(self):\n        self.data = {}\n    def save(self, key, value):\n        self.data[key] = value\n        return value\n\nclass Service:\n    def __init__(self, repo):\n        self.repo = repo\n    def place(self, order_id, total):\n        if total <= 0:\n            raise ValueError(\"bad total\")\n        return self.repo.save(order_id, {\"id\": order_id, \"total\": total})\n\nprint(Service(Repo()).place(\"ORD-1\", 40))\n",
